import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = reader.readLine().split(" ");
        int n = Integer.parseInt(inputLine[0]);
        long tmp = Long.parseLong(inputLine[1]);
        if(n <= tmp) {
            System.out.println(0);
            return;
        }
        int k = (int)tmp;
        long[] factorials = new long[400001];
        long[] invFactorials = new long[400001];
        initializeFactorials(factorials, invFactorials, 400000);
        long totalComb = nCr(n, n - k, factorials, invFactorials);
        long totalAnswer = 0;
        int signFlag = 1;
        for(int i = n - k; i >= 1; i--) {
            long comb = nCr(n - k, i, factorials, invFactorials);
            long powerVal = pow(i, n);
            totalAnswer = (totalAnswer + signFlag * comb * powerVal) % MOD;
            signFlag *= -1;
        }
        totalAnswer = (totalAnswer * totalComb) % MOD;
        if(k != 0) totalAnswer = (totalAnswer * 2) % MOD;
        System.out.println((totalAnswer + MOD) % MOD);
    }

    static void initializeFactorials(long[] fact, long[] invFact, int max) {
        fact[0] = 1;
        for(int i=1;i<=max;i++) {
            fact[i] = (fact[i-1] * i) % MOD;
        }
        invFact[max] = pow(fact[max], MOD - 2);
        for(int i=max-1;i>=0;i--) {
            invFact[i] = (invFact[i+1] * (i+1)) % MOD;
        }
    }

    static long nCr(int n, int r, long[] fact, long[] invFact) {
        if(n<r) return 0;
        return (((fact[n] * invFact[r]) % MOD) * invFact[n - r]) % MOD;
    }

    static long pow(long base, int exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }
}
